$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$sourcePath='D:\projects\mtp-native-moe-source-r2.json'
$m=[IO.File]::ReadAllText($sourcePath)|ConvertFrom-Json
function Verify-File([string]$Path,[string]$Sha){if((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $Sha){throw ('Changed input: '+$Path)}}
function Check-Run([string]$Path){
 $r=[IO.File]::ReadAllText($Path)|ConvertFrom-Json
 if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass -or @($r.after_processes).Count -ne 0){throw ('Unqualified run: '+$Path)}
 foreach($check in $r.host_checks.PSObject.Properties){if(-not $check.Value){throw 'Failed host check'}}
}
function Run-Git([string[]]$GitArguments){
 $psi=New-Object Diagnostics.ProcessStartInfo
 $psi.FileName='git.exe';$psi.UseShellExecute=$false;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true
 $psi.Arguments=($GitArguments|ForEach-Object {'"'+$_.Replace('"','\"')+'"'}) -join ' '
 $p=New-Object Diagnostics.Process;$p.StartInfo=$psi
 if(-not $p.Start()){throw 'Git did not start'}
 $outTask=$p.StandardOutput.ReadToEndAsync();$errTask=$p.StandardError.ReadToEndAsync()
 if(-not $p.WaitForExit(30000)){try{$p.Kill()}catch{};throw 'Git timeout'}
 $stdout=$outTask.GetAwaiter().GetResult();$stderr=$errTask.GetAwaiter().GetResult()
 if($p.ExitCode -ne 0){throw ('Git failed: '+$stderr)}
 return $stdout.Trim()
}
function Run-Tar([string[]]$TarArguments){
 $psi=New-Object Diagnostics.ProcessStartInfo
 $psi.FileName='tar.exe';$psi.UseShellExecute=$false;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true
 $psi.Arguments=($TarArguments|ForEach-Object {'"'+$_.Replace('"','\"')+'"'}) -join ' '
 $p=New-Object Diagnostics.Process;$p.StartInfo=$psi
 if(-not $p.Start()){throw 'Tar did not start'}
 $outTask=$p.StandardOutput.ReadToEndAsync();$errTask=$p.StandardError.ReadToEndAsync()
 if(-not $p.WaitForExit(120000)){try{$p.Kill()}catch{};throw 'Tar timeout'}
 $stdout=$outTask.GetAwaiter().GetResult();$stderr=$errTask.GetAwaiter().GetResult()
 if($p.ExitCode -ne 0){throw ('Tar failed: '+$stderr)}
 return $stdout.Trim()
}
Verify-File $PSCommandPath $m.script_sha256
$binding=[IO.File]::ReadAllText('D:\projects\mtp-native-moe-dispatch-binding-r2.json')|ConvertFrom-Json
Verify-File $sourcePath $binding.source_manifest_sha256
$activePath=Join-Path $m.active_run_remote_directory 'run-record.json'
Verify-File $activePath $binding.completed_active_run_sha256
$active=[IO.File]::ReadAllText($activePath)|ConvertFrom-Json
if(-not $active.host_checks_pass -or @($active.after_processes).Count -ne 0 -or
   -not $active.host.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Prior long run cleanup or host checks failed'}
foreach($check in $active.host_checks.PSObject.Properties){if(-not $check.Value){throw 'Prior host check failed'}}
Verify-File (Join-Path $m.active_run_remote_directory 'launch.json') $m.active_launch_sha256
$repo=$m.repo.Replace('/','\');$seed=$m.seed.Replace('/','\');$sha=$m.source_commit
$bundle=Join-Path 'D:\projects' $m.bundle;Verify-File $bundle $m.bundle_sha256
if(Test-Path $repo){throw 'Native probe checkout already exists'}
$null=Run-Git -GitArguments @('-C',$seed,'fetch',$bundle,'HEAD')
$null=Run-Git -GitArguments @('-C',$seed,'worktree','add','--detach',$repo,$sha)
if((Run-Git -GitArguments @('-C',$repo,'rev-parse','HEAD')) -ne $sha -or (Run-Git -GitArguments @('-C',$repo,'status','--porcelain'))){throw 'Source mismatch'}
foreach($item in $m.source_sha256.PSObject.Properties){Verify-File (Join-Path $repo $item.Name) $item.Value}
$data=$m.data.Replace('/','\');$archive=Join-Path 'D:\projects' $m.archive
Verify-File $archive $m.archive_sha256
if(Test-Path $data){throw 'Native probe data already exists'}
$null=New-Item -ItemType Directory -Path $data
$null=Run-Tar -TarArguments @('-xf',$archive,'-C',$data)
foreach($f in @($m.files)+@($m.tables)){
 if((Get-Item -LiteralPath $f.path).Length -ne $f.bytes){throw ('Input size changed: '+$f.path)}
 Verify-File $f.path $f.sha256
}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
$out=Join-Path $repo 'build\mtp-native-moe-r1'
$null=New-Item -ItemType Directory -Path $out
$guard=Join-Path $repo 'scripts\baiying_guarded_inference.ps1'
$failed=$false
try{
Verify-File (Join-Path $m.model 'model.safetensors.index.json') $m.model_index_sha256
$weightDirectory=Join-Path $m.data 'model-weights'
if(Test-Path $weightDirectory){throw 'Derived model weights already exist'}
$null=New-Item -ItemType Directory -Path $weightDirectory
$modelWeightRecords=@()
foreach($weight in $m.model_weights){
 $timer=[Diagnostics.Stopwatch]::StartNew()
 $hasher=[Security.Cryptography.SHA256]::Create();$output=$null;$total=0L
 try{
  if($weight.export_path){$output=[IO.File]::Open($weight.export_path,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)}
  foreach($span in $weight.spans){
   $path=Join-Path $m.model $span.shard
   $tensorStream=[IO.File]::Open($path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read)
   try{
    if($tensorStream.Length -ne $span.shard_file_bytes){throw 'Original shard size changed'}
    $reader=[IO.BinaryReader]::new($tensorStream,[Text.Encoding]::UTF8,$true)
    try{
     $headerLength=$reader.ReadUInt64()
     if($headerLength -gt 16777216 -or $headerLength -gt $tensorStream.Length-8){throw 'Model header bound'}
     $headerBytes=$reader.ReadBytes([int]$headerLength)
     if($headerBytes.Length -ne $headerLength){throw 'Short model header'}
    }finally{$reader.Dispose()}
    $headerHasher=[Security.Cryptography.SHA256]::Create()
    try{$headerSha=[BitConverter]::ToString($headerHasher.ComputeHash($headerBytes)).Replace('-','').ToLowerInvariant()}
    finally{$headerHasher.Dispose()}
    if($headerSha -ne $span.header_sha256){throw 'Original model header changed'}
    $header=[Text.Encoding]::UTF8.GetString($headerBytes)|ConvertFrom-Json
    $property=$header.PSObject.Properties[$span.name]
    if(-not $property){throw 'Original tensor missing'}
    $tensor=$property.Value
    if($tensor.dtype -ne $span.dtype -or ($tensor.shape -join ',') -ne ($span.shape -join ',') -or
       ($tensor.data_offsets -join ',') -ne ($span.data_offsets -join ',') -or
       8L+$headerLength+[long]$tensor.data_offsets[0] -ne $span.absolute_begin -or
       [long]$tensor.data_offsets[1]-[long]$tensor.data_offsets[0] -ne $span.bytes){throw 'Original tensor layout changed'}
    $null=$tensorStream.Seek([long]$span.absolute_begin,[IO.SeekOrigin]::Begin)
    $remaining=[long]$span.bytes;$buffer=New-Object byte[] 4194304
    while($remaining -gt 0){
     if($timer.Elapsed.TotalSeconds -gt $m.model_tensor_read_timeout_seconds){throw 'Original model tensor read timeout'}
     $count=$tensorStream.Read($buffer,0,[int][Math]::Min($remaining,$buffer.Length))
     if($count -le 0){throw 'Short original tensor read'}
     $null=$hasher.TransformBlock($buffer,0,$count,$buffer,0)
     if($output){$output.Write($buffer,0,$count)}
     $remaining-=$count;$total+=$count
    }
   }finally{$tensorStream.Dispose()}
  }
  $null=$hasher.TransformFinalBlock([byte[]]@(),0,0)
  $digest=[BitConverter]::ToString($hasher.Hash).Replace('-','').ToLowerInvariant()
 }finally{if($output){$output.Dispose()};$hasher.Dispose()}
 if($total -ne $weight.bytes -or $digest -ne $weight.sha256){throw 'Original weight content differs from qualified reference'}
 if($weight.export_path){Verify-File $weight.export_path $weight.sha256}
 $modelWeightRecords+=@{label=$weight.label;bytes=$total;sha256=$digest;spans=$weight.spans;
  export_path=$weight.export_path;read_seconds=$timer.Elapsed.TotalSeconds;read_timeout_seconds=$m.model_tensor_read_timeout_seconds;pass=$true}
}
[IO.File]::WriteAllText((Join-Path $out 'model-weight-bindings.json'),($modelWeightRecords|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false))

 foreach($program in $m.programs){
  $exe=Join-Path $out ($program.name+'.exe')
  $spec=[ordered]@{
   executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
   arguments=@('-std=c++17','-O2','-fno-fast-math','-fno-reciprocal-math','-ffp-contract=off','--offload-arch=gfx1151','-I',$repo,(Join-Path $repo $program.source),'-o',$exe)
   working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=$m.script_sha256
   model='none; compile original MTP component comparison';model_loaded=$false;inference_acceptance=$false
   source_manifest_sha256=$binding.source_manifest_sha256;source_inputs=$m.source_sha256
  }
  $specPath=Join-Path $out ($program.name+'-build-spec.json')
  [IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false))
  & $guard -SpecPath $specPath -OutDir (Join-Path $out ($program.name+'-build')) -TimeoutSeconds $m.compile_timeout_seconds|Out-Null
  Check-Run (Join-Path $out ($program.name+'-build\run-record.json'))
 }
 foreach($case in $m.cases){
  $exe=Join-Path $out ($case.program+'.exe')
  $spec=[ordered]@{
   executable=$exe;executable_sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()
   arguments=@($case.arguments);working_directory=$repo;repo_commit=$sha
   command_file=$PSCommandPath;command_file_sha256=$m.script_sha256;source_manifest_sha256=$binding.source_manifest_sha256
   input_artifacts=@($m.files)+@($m.tables);case=$case;model_tensor_bindings=$modelWeightRecords
   model='D:\models\Qwen3.6-35B-A3B; original gb10-4t MTP operands and comparison outputs'
   reference_host=$m.reference_host;reference_model=$m.reference_model
   model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false
  }
  $specPath=Join-Path $out ($case.name+'-spec.json');$runOut=Join-Path $out $case.name
  [IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 18),[Text.UTF8Encoding]::new($false))
  & $guard -SpecPath $specPath -OutDir $runOut -TimeoutSeconds $case.timeout_seconds|Out-Null
  Check-Run (Join-Path $runOut 'run-record.json')
  $rows=@(Get-Content -LiteralPath (Join-Path $runOut 'product.stdout.jsonl')|ForEach-Object {$_|ConvertFrom-Json})
  if($rows.Count -ne $case.expected_reports){throw 'Missing component reports'}
  foreach($row in $rows){if(-not $row.passed){throw 'Numerical or memory-boundary mismatch'}}
  [ordered]@{case=$case.name;reports=$rows}|ConvertTo-Json -Depth 7 -Compress
 }
}catch{$failed=$true;[Console]::Error.WriteLine($_.ToString())}
finally{
 $compact=Join-Path 'D:\projects' $m.evidence_archive
 if(Test-Path $compact){throw 'Evidence archive exists'}
 $null=Run-Tar -TarArguments @('-czf',$compact,'--exclude=*.exe','-C',$out,'.')
 [ordered]@{evidence_archive=$compact;sha256=(Get-FileHash $compact -Algorithm SHA256).Hash.ToLowerInvariant();bytes=(Get-Item $compact).Length}|ConvertTo-Json -Compress
}
if($failed){exit 1}
